def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find 4-connected components of color 1; the largest is the source figure.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            comps.append(comp)
    shape = max(comps, key=len)
    shape_set = set(shape)
    r0, r1 = min(r for r,c in shape), max(r for r,c in shape)
    c0, c1 = min(c for r,c in shape), max(c for r,c in shape)
    # The separate color key is a stripe: read its palette left-to-right.
    palette_by_col = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in shape_set:
                palette_by_col.setdefault(c, grid[r][c])
    colors = [palette_by_col[c] for c in sorted(palette_by_col)]
    out = [[0] * w for _ in range(h)]
    mask = [(r-r0, c-c0) for r,c in shape]
    sh = r1-r0+1
    source_color_index = colors.index(1)
    start = r0 - source_color_index * sh
    for i, color in enumerate(colors):
        top = start + i * sh
        for dr, dc in mask:
            rr, cc = top + dr, c0 + dc
            if 0 <= rr < h:
                out[rr][cc] = color
    return out

